        segments = []
        seg = [core_cols[0]]
        for x in core_cols[1:]:
            if x == seg[-1] + 1:
                seg.append(x)
            else:
                segments.append(seg)
                seg = [x]
        segments.append(seg)
        longest = max(segments, key=len)
        x0c, x1c = longest[0], longest[-1]
    else:
        x0c, x1c = x0, x1
    core_bbox[c] = (y0c, y1c, x0c, x1c)

# Identify bar components per color
